        }
        if (r.ReadBool())
        {
            v.Pitch = unchecked((ushort)(b.Pitch + r.ReadDelta()));
        }
        if (r.ReadBool())
        {
            v.LookYaw = unchecked((sbyte)((int)b.LookYaw + r.ReadDelta()));
        }
        if (r.ReadBool())
        {
            v.LookPitch = unchecked((sbyte)((int)b.LookPitch + r.ReadDelta()));
        }
        if (r.ReadBool())
